pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddress, address controllerAddress) public {
        vm.assume(oracleAddress != address(0));
        vm.assume(controllerAddress != address(0));

        // Deploy mock oracle and controller contracts
        vm.etch(oracleAddress, hex"02");
        vm.etch(controllerAddress, hex"02");

        // Set up Controller mock to return oracleAddress when oracle() is called
        vm.mockCall(controllerAddress, abi.encodeWithSignature("oracle()"), abi.encode(oracleAddress));
        vm.mockCall(controllerAddress, abi.encodeWithSignature("isContract(address)"), abi.encode(true));
        vm.mockCall(controllerAddress, abi.encodeWithSignature("isProduct(address)"), abi.encode(true));
        vm.mockCall(controllerAddress, abi.encodeWithSignature("owner(uint256)"), abi.encode(address(this)));
        vm.mockCall(controllerAddress, abi.encodeWithSignature("coordinatorFor(address)"), abi.encode(uint256(0)));
        vm.mockCall(controllerAddress, abi.encodeWithSignature("collateral()"), abi.encode(address(0x1234)));

        // Set up product info
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TEST";
        info.oracle = IOracleProvider(address(0x5678));
        // Initialize oracle mock
        vm.etch(address(0x5678), hex"02");

        // Initialize C contract (this will call __UPayoffProvider__initialize which calls _updateOracle)
        vm.prank(controllerAddress);
        try c.initialize(info) {} catch {}

        // The key property: oracle() must return exactly the address that was initialized
        // Bug returns address(0) instead
        assertEq(address(c.oracle()), address(info.oracle));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // The test requires that c is initialized to a valid state so that oracle() returns a meaningful address.
        // We craft a minimal ProductInfo that satisfies the initializer checks and sets a canonical oracle address.
        // We use a dummy contract address with code to pass isContract in _updateOracle.
        // Because the initializer checks msg.sender is the controller (IController), we deploy a mock that implements the necessary functions.
        // However, the test must avoid complex mocking since only vm.deal/vm.prank/vm.assume are allowed.
        // Instead, we directly call the initializer by pranking the correct controller address.
        // For simplicity, we will make the test assume that c is already deployed and initialized; in practice a Foundry setUp would deploy and initialize it.
        // The key fuzzed parameter is the actor who calls oracle().
    }

    function testFuzz_property(address actor) public {
        // We need to initialize c so that oracle() returns a known, non-zero, non-msg.sender address.
        // Since we cannot easily mock the controller, we exploit the fact that the initializer modifier checks _constructing() which returns false after deployment.
        // In the test environment, new C() deploys the contract, so _constructing() returns false.
        // The initializer modifier allows initializing only once; we need to supply a valid ProductInfo.
        // To avoid complex setup, we will use a known address with code for the oracle (e.g., address(this)).
        // We will prank as the controller (which is itself for simplicity) to call initialize.
        // This is allowed.

        // Build a minimal ProductInfo struct
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        // oracle: use address(this) which is a contract (has code)
        info.oracle = IOracleProvider(address(this));
        // payoffDefinition: need a valid one; use PASSTHROUGH from the library
        // PayoffDefinitionLib.PayoffType.PASSTHROUGH = 0, PayoffDirection.NEITHER = 0
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.NEITHER,
            data: bytes30(0)
        });
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // The initializer expects msg.sender to be the controller (IController).
        // We will make the caller the controller by pranking as the controller address.
        // For simplicity, we use the contract itself as the controller (since it will be the deployer).
        vm.prank(address(this));
        c.initialize(info);

        // Now the oracle is set to address(this).
        // The oracle() function should return address(this) in the reference version.
        // The buggy version returns msg.sender.
        // We will call oracle() from a different actor (actor).
        // We need to ensure actor is not the same as address(this) to trigger the difference.
        vm.assume(actor != address(this));
        vm.prank(actor);
        IOracleProvider returned = c.oracle();

        // Property: oracle() must return the originally set oracle address, not the caller.
        assertEq(address(returned), address(this), "oracle() should return the initialized oracle address");
    }
}

