pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 price) public {
        // admissible domain: price > 0 to avoid division by zero in transform
        vm.assume(price > 0);
        // mock a simple oracle that returns a known price
        MockOracle oracle = new MockOracle(price);
        // prepare product info with a pass-through payoff (no transformation)
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition(PayoffDefinitionLib.PayoffType.PASS_THROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0));
        info.oracle = IOracleProvider(address(oracle));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(1e17);
        info.makerFee = UFixed18.wrap(1e17);
        info.takerFee = UFixed18.wrap(1e17);
        info.positionFee = UFixed18.wrap(1e17);
        info.makerLimit = UFixed18.wrap(1000e18);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(int128(0)),
            PackedFixed18.wrap(int128(100e18)),
            PackedFixed18.wrap(int128(80e18)),
            PackedUFixed18.wrap(uint128(0.8e18))
        );
        // initialize the contract
        c.initialize(info);
        // get the transformed price via currentVersion which uses oracle()
        IOracleProvider.OracleVersion memory transformed = c.currentVersion();
        // The general rule: transformed price must match the actual oracle's raw price
        // (pass-through payoff means price = raw price).
        // Reference C uses the real oracle address, so transformed.price equals oracle's price.
        // Mutant uses address(this) which is not the oracle, so oracle() returns a contract without the correct price.
        assertTrue(Fixed18.unwrap(transformed.price) == price * 1e18);
    }
}

contract MockOracle is IOracleProvider {
    uint256 public price;
    constructor(uint256 _price) { price = _price; }
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(int256(price * 1e18)));
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(int256(price * 1e18)));
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion(1, block.timestamp, Fixed18.wrap(int256(price * 1e18)));
    }
}

