pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        string memory name,
        string memory symbol,
        bytes30 payoffData,
        uint8 payoffTypeInt,
        uint8 payoffDirectionInt
    ) public {
        // Admissible: payoffType 0-6 and payoffDirection 0-2 as per enum ranges
        vm.assume(payoffTypeInt < 7);
        vm.assume(payoffDirectionInt < 3);

        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(payoffTypeInt);
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection(payoffDirectionInt);
        PayoffDefinition memory def = PayoffDefinition(pType, pDir, payoffData);

        // Only initialize if the payoff definition is valid; otherwise skip
        if (!def.valid()) {
            return;
        }

        IOracleProvider oracle = IOracleProvider(address(0x1)); // dummy contract address, won't be called
        vm.etch(address(oracle), hex"00"); // treat as contract
        IProduct.ProductInfo memory info;
        info.name = name;
        info.symbol = symbol;
        info.payoffDefinition = def;
        info.oracle = oracle;
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedFixed18.wrap(0),
            PackedUFixed18.wrap(0)
        );

        // Deploy and initialize C with controller as itself (this contract acts as controller for initializer)
        vm.prank(address(this));
        c.initialize(info);

        // Retrieve the returned payoff definition
        PayoffDefinition memory returnedDef = c.payoffDefinition();

        // The general rule: returned definition must be byte-equal to the definition passed during initialization
        assertTrue(
            returnedDef.payoffType == def.payoffType &&
            returnedDef.payoffDirection == def.payoffDirection &&
            returnedDef.data == def.data
        );
    }
}

