        IProduct.ProductInfo memory info = IProduct.ProductInfo(
            "test", "TST",
            PayoffDefinition(PayoffDefinitionLib.PayoffType.PASS_THROUGH, PayoffDefinitionLib.PayoffDirection.LONG, data),
