type UFixed18 is uint256;
library UFixed18Lib {
    UFixed18 public constant ZERO = UFixed18.wrap(0);
    UFixed18 public constant ONE = UFixed18.wrap(1e18);
    UFixed18 public constant MAX = UFixed18.wrap(type(uint256).max);
}
