// Minimal mock oracle that simulates version advancement.
contract MockOracle {
    uint256 public latestVersion;
    uint256 public constant BASE_TIMESTAMP = 1_000_000;
    uint256 public immutable versionIncrement;

    constructor(uint256 _versionIncrement) {
        versionIncrement = _versionIncrement;
        // Start with version 0 and timestamp 0.
        latestVersion = 0;
    }

    function sync() external returns (IOracleProvider.OracleVersion memory) {
        // Advance to the next version.
        latestVersion++;
        return currentVersion();
    }

    function syncToVersion(uint256 target) external {
        // Advance to a specific version.
        require(target > latestVersion, "can only go forward");
        latestVersion = target;
    }

    function currentVersion() public view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(
            latestVersion,
            latestVersion == 0 ? 0 : BASE_TIMESTAMP + latestVersion * versionIncrement,
            Fixed18.wrap(int256(latestVersion) * 1e18)
        );
    }

    function atVersion(uint256 version) public view returns (IOracleProvider.OracleVersion memory) {
        require(version <= latestVersion, "future version");
        if (version == 0) {
            return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
        }
        return IOracleProvider.OracleVersion(
            version,
            BASE_TIMESTAMP + version * versionIncrement,
            Fixed18.wrap(int256(version) * 1e18)
        );
    }
}

