pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracle, bytes30 data) public {
        vm.assume(oracle != address(0));
        vm.assume(oracle.code.length > 0);
        vm.mockCall(oracle, abi.encodeWithSignature("currentVersion()"), abi.encode(uint256(1), uint256(1000), int256(5e18)));
        vm.mockCall(oracle, abi.encodeWithSignature("sync()"), abi.encode(uint256(1), uint256(1000), int256(5e18)));
        PayoffDefinition memory pd = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
            data: data
        });
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: pd,
            oracle: IOracleProvider(oracle),
            maintenance: UFixed18Lib.ZERO,
            fundingFee: UFixed18Lib.ZERO,
            makerFee: UFixed18Lib.ZERO,
            takerFee: UFixed18Lib.ZERO,
            positionFee: UFixed18Lib.ZERO,
            makerLimit: UFixed18Lib.MAX,
            utilizationCurve: JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(1e18)})
        });
        vm.prank(address(this));
        c.initialize(info);
        IOracleProvider.OracleVersion memory returned = c.currentVersion();
        IOracleProvider.OracleVersion memory expected = c.currentVersion();
        assertTrue(expected.price == returned.price);
    }
}

